"""
backend/libvirt_manager.py

Manages the libvirt connection and domain lifecycle for the BulwarkOS
control panel. Runs libvirt's event loop in a dedicated background thread
so domain state-change events are delivered without blocking the GTK main loop.

All GTK interaction is done via GLib.idle_add() callbacks — never call any
Gtk/Adw method from within a libvirt event callback directly.
"""

import json
import os
import threading
from pathlib import Path

import libvirt
from gi.repository import GLib
from typing import Callable

# Connection URI — always the system instance
LIBVIRT_URI = "qemu:///system"

# User-editable trust overrides stored here.
# Created on first run if absent.
TRUST_CONFIG_PATH = Path(
    os.environ.get("XDG_CONFIG_HOME", Path.home() / ".config")
) / "bulwarkos" / "vm-trust.json"

# Domain states as reported by libvirt
_STATE_NAMES = {
    libvirt.VIR_DOMAIN_NOSTATE:     "Unknown",
    libvirt.VIR_DOMAIN_RUNNING:     "Running",
    libvirt.VIR_DOMAIN_BLOCKED:     "Blocked",
    libvirt.VIR_DOMAIN_PAUSED:      "Paused",
    libvirt.VIR_DOMAIN_SHUTDOWN:    "Shutting down",
    libvirt.VIR_DOMAIN_SHUTOFF:     "Stopped",
    libvirt.VIR_DOMAIN_CRASHED:     "Crashed",
    libvirt.VIR_DOMAIN_PMSUSPENDED: "Suspended",
}

# Built-in BulwarkOS VM metadata — fixed trust levels for system VMs.
# All other domains discovered via libvirt are shown with user-editable
# trust levels loaded from TRUST_CONFIG_PATH.
_BUILTIN_META: dict[str, dict] = {
    "sys-net":      {"label": "sys-net",      "trust": "system",  "icon": "network-wired-symbolic",         "system_locked": True},
    "sys-firewall": {"label": "sys-firewall",  "trust": "system",  "icon": "firewall-symbolic",              "system_locked": True},
    "personal":     {"label": "Personal",      "trust": "trusted",  "icon": "user-home-symbolic",             "system_locked": False},
    "work":         {"label": "Work",          "trust": "trusted",    "icon": "briefcase-symbolic",             "system_locked": False},
    "banking":      {"label": "Banking",       "trust": "vault", "icon": "bank-symbolic",                  "system_locked": False},
    "development":  {"label": "Development",   "trust": "development",     "icon": "code-symbolic",                  "system_locked": False},
    "disposable":   {"label": "Disposable",    "trust": "untrusted",     "icon": "user-trash-symbolic",            "system_locked": False},
    "media":        {"label": "Media",         "trust": "untrusted",     "icon": "multimedia-player-symbolic",     "system_locked": False},
    "gaming-vm":    {"label": "Gaming",        "trust": "untrusted",     "icon": "applications-games-symbolic",   "system_locked": False},
}

# ---------------------------------------------------------------------------
# Trust level definitions
# ---------------------------------------------------------------------------
# Built-in trust levels ship with fixed colours and sort priorities.
# Users can add custom levels via the trust editor — stored in vm-trust.json
# under the top-level "custom_levels" key alongside per-VM overrides.
#
# Colour values are used in the sidebar dot and the detail view badge.
# System is the only locked level — users cannot assign it to non-system VMs.

DEFAULT_TRUST_LEVELS: dict[str, dict] = {
    "system":       {"label": "System",       "color": "#546ac1", "sort": 0, "locked": True},
    "trusted":      {"label": "Trusted",       "color": "#2aad4d", "sort": 1, "locked": False},
    "untrusted":    {"label": "Untrusted",     "color": "#ed7f11", "sort": 2, "locked": False},
    "least_trusted":{"label": "Least Trusted", "color": "#781d1d", "sort": 3, "locked": False},
    "vault":        {"label": "Vault",         "color": "#9d1cff", "sort": 4, "locked": False},
    "development":  {"label": "Development",   "color": "#f5e040", "sort": 5, "locked": False},
    "unknown":      {"label": "Unknown",       "color": "#888888", "sort": 99,"locked": False},
}

# Convenience aliases kept for compatibility with existing code
TRUST_LEVELS: dict[str, int] = {k: v["sort"] for k, v in DEFAULT_TRUST_LEVELS.items()}
TRUST_LABELS: dict[str, str] = {k: v["label"] for k, v in DEFAULT_TRUST_LEVELS.items()}
TRUST_COLORS: dict[str, str] = {k: v["color"] for k, v in DEFAULT_TRUST_LEVELS.items()}


def _merge_trust_defs(user_config: dict) -> dict[str, dict]:
    """
    Merge built-in trust level definitions with any user-defined custom levels.
    Custom levels are stored under user_config["_trust_defs"].
    Returns a complete dict keyed by trust ID.
    """
    merged = dict(DEFAULT_TRUST_LEVELS)
    for key, val in user_config.get("_trust_defs", {}).items():
        if key in merged and merged[key].get("locked"):
            continue  # never override system
        merged[key] = {
            "label":  val.get("label", key),
            "color":  val.get("color", "#888888"),
            "sort":   val.get("sort", 50),
            "locked": False,
        }
    return merged


def _load_trust_config() -> dict[str, dict]:
    """Load user-defined VM metadata overrides from disk."""
    if not TRUST_CONFIG_PATH.exists():
        return {}
    try:
        return json.loads(TRUST_CONFIG_PATH.read_text())
    except (json.JSONDecodeError, OSError):
        return {}


def _save_trust_config(config: dict[str, dict]):
    """Persist user-defined VM metadata overrides to disk."""
    TRUST_CONFIG_PATH.parent.mkdir(parents=True, exist_ok=True)
    TRUST_CONFIG_PATH.write_text(json.dumps(config, indent=2))


def _resolve_meta(name: str, user_config: dict) -> dict:
    """
    Returns metadata for a domain by merging (highest priority first):
      1. Per-VM user overrides  (label, trust, icon)  from vm-trust.json
      2. Built-in BulwarkOS defaults
      3. Generic fallback for unknown VMs
    system_locked is taken from built-ins only — cannot be user-overridden.
    """
    builtin      = _BUILTIN_META.get(name, {})
    # Per-VM overrides live under the domain name key;
    # top-level keys starting with "_" are used for config metadata
    user_over    = {k: v for k, v in user_config.get(name, {}).items()}
    system_locked = builtin.get("system_locked", False)

    return {
        "label":         user_over.get("label",  builtin.get("label",  name)),
        "trust":         (builtin["trust"] if system_locked
                          else user_over.get("trust", builtin.get("trust", "unknown"))),
        "icon":          user_over.get("icon",   builtin.get("icon",   "computer-symbolic")),
        "system_locked": system_locked,
    }


class DomainInfo:
    """Lightweight snapshot of a domain's current state."""
    __slots__ = ("name", "uuid", "state", "state_name",
                 "vcpus", "max_memory_kb", "meta")

    def __init__(self, domain: libvirt.virDomain, user_config: dict):
        self.name          = domain.name()
        self.uuid          = domain.UUIDString()
        state, _reason     = domain.state()
        self.state         = state
        self.state_name    = _STATE_NAMES.get(state, "Unknown")
        self.meta          = _resolve_meta(self.name, user_config)
        try:
            info               = domain.info()
            self.vcpus         = info[3]
            self.max_memory_kb = info[1]
        except libvirt.libvirtError:
            self.vcpus         = 0
            self.max_memory_kb = 0

    @property
    def is_running(self) -> bool:
        return self.state == libvirt.VIR_DOMAIN_RUNNING

    @property
    def is_stopped(self) -> bool:
        return self.state == libvirt.VIR_DOMAIN_SHUTOFF

    @property
    def is_paused(self) -> bool:
        return self.state == libvirt.VIR_DOMAIN_PAUSED

    @property
    def is_system_locked(self) -> bool:
        return self.meta.get("system_locked", False)


DomainListCallback = Callable[[list[DomainInfo]], None]


class LibvirtManager:
    """
    Owns the libvirt connection and drives its event loop from a background
    thread. Discovers ALL domains on qemu:///system (not just BulwarkOS ones)
    and notifies the UI layer on every state change.
    """

    def __init__(self, on_domains_changed: DomainListCallback):
        self._conn: libvirt.virConnect | None = None
        self._on_changed = on_domains_changed
        self._stop_event = threading.Event()
        self._event_thread: threading.Thread | None = None
        self._callback_ids: list[int] = []
        self._user_config: dict = _load_trust_config()

    # ------------------------------------------------------------------ #
    # Lifecycle                                                            #
    # ------------------------------------------------------------------ #

    def start(self):
        libvirt.virEventRegisterDefaultImpl()
        try:
            self._conn = libvirt.open(LIBVIRT_URI)
        except libvirt.libvirtError as e:
            GLib.idle_add(self._on_changed, [])
            print(f"[LibvirtManager] Connection failed: {e}")
            return

        for event_id in (libvirt.VIR_DOMAIN_EVENT_ID_LIFECYCLE,):
            cb_id = self._conn.domainEventRegisterAny(
                None, event_id, self._on_lifecycle_event, None
            )
            self._callback_ids.append(cb_id)

        self._event_thread = threading.Thread(
            target=self._event_loop, name="libvirt-events", daemon=True
        )
        self._event_thread.start()
        self._notify()

    def stop(self):
        self._stop_event.set()
        if self._conn:
            for cb_id in self._callback_ids:
                try:
                    self._conn.domainEventDeregisterAny(cb_id)
                except libvirt.libvirtError:
                    pass
            try:
                self._conn.close()
            except libvirt.libvirtError:
                pass
        self._conn = None

    # ------------------------------------------------------------------ #
    # Event loop                                                           #
    # ------------------------------------------------------------------ #

    def _event_loop(self):
        while not self._stop_event.is_set():
            try:
                libvirt.virEventRunDefaultImpl()
            except Exception as e:
                print(f"[LibvirtManager] Event loop error: {e}")
                break

    def _on_lifecycle_event(self, conn, domain, event, detail, opaque):
        GLib.idle_add(self._notify)

    def _notify(self):
        domains = self.list_domains()
        self._on_changed(domains)
        return GLib.SOURCE_REMOVE

    # ------------------------------------------------------------------ #
    # Domain queries                                                        #
    # ------------------------------------------------------------------ #

    def list_domains(self) -> list[DomainInfo]:
        """
        Returns DomainInfo for ALL domains on qemu:///system,
        sorted by trust level then name.
        Includes manually created VMs, not just BulwarkOS ones.
        """
        if not self._conn:
            return []
        try:
            all_domains = self._conn.listAllDomains()
        except libvirt.libvirtError:
            return []

        def sort_key(d: libvirt.virDomain):
            meta  = _resolve_meta(d.name(), self._user_config)
            trust = meta.get("trust", "unknown")
            return (TRUST_LEVELS.get(trust, 99), d.name())

        all_domains.sort(key=sort_key)

        results = []
        for d in all_domains:
            try:
                results.append(DomainInfo(d, self._user_config))
            except libvirt.libvirtError:
                pass
        return results

    def get_domain(self, name: str) -> libvirt.virDomain | None:
        if not self._conn:
            return None
        try:
            return self._conn.lookupByName(name)
        except libvirt.libvirtError:
            return None

    # ------------------------------------------------------------------ #
    # Trust level management                                               #
    # ------------------------------------------------------------------ #

    def set_trust(self, name: str, trust: str, label: str | None = None) -> tuple[bool, str]:
        """
        Persist a user-defined trust level (and optionally display label)
        for a VM. System VMs (sys-net, sys-firewall) are silently ignored.
        """
        builtin = _BUILTIN_META.get(name, {})
        if builtin.get("system_locked", False):
            return False, f"{name} is a system VM — trust level cannot be changed."

        # Validate against the live merged defs — this includes user-defined
        # custom levels that do not appear in the static TRUST_LEVELS dict.
        live_defs = _merge_trust_defs(self._user_config)
        if trust not in live_defs:
            return False, f"Unknown trust level '{trust}'."

        entry = self._user_config.get(name, {})
        entry["trust"] = trust
        if label:
            entry["label"] = label
        self._user_config[name] = entry

        try:
            _save_trust_config(self._user_config)
        except OSError as e:
            return False, f"Failed to save trust config: {e}"

        self._notify()
        return True, f"Trust level for {name} set to {trust}."

    def set_label(self, name: str, label: str) -> tuple[bool, str]:
        """Set a custom display label for any non-system VM."""
        builtin = _BUILTIN_META.get(name, {})
        if builtin.get("system_locked", False):
            return False, f"{name} is a system VM — label cannot be changed."
        entry = self._user_config.get(name, {})
        entry["label"] = label.strip() or name
        self._user_config[name] = entry
        try:
            _save_trust_config(self._user_config)
        except OSError as e:
            return False, f"Failed to save label: {e}"
        self._notify()
        return True, f"Label for {name} updated."

    # ------------------------------------------------------------------ #
    # Domain control                                                        #
    # ------------------------------------------------------------------ #

    def start_domain(self, name: str) -> tuple[bool, str]:
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            domain.create()
            return True, f"{name} started."
        except libvirt.libvirtError as e:
            return False, str(e)

    def shutdown_domain(self, name: str) -> tuple[bool, str]:
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            domain.shutdown()
            return True, f"{name} shutdown requested."
        except libvirt.libvirtError as e:
            return False, str(e)

    def force_stop_domain(self, name: str) -> tuple[bool, str]:
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            domain.destroy()
            return True, f"{name} force stopped."
        except libvirt.libvirtError as e:
            return False, str(e)

    def restart_domain(self, name: str) -> tuple[bool, str]:
        """Graceful ACPI reboot."""
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            domain.reboot(0)
            return True, f"{name} reboot requested."
        except libvirt.libvirtError as e:
            return False, str(e)

    def reset_domain(self, name: str) -> tuple[bool, str]:
        """Hard reset — like pressing the physical reset button."""
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            domain.reset()
            return True, f"{name} reset."
        except libvirt.libvirtError as e:
            return False, str(e)

    def pause_domain(self, name: str) -> tuple[bool, str]:
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            domain.suspend()
            return True, f"{name} paused."
        except libvirt.libvirtError as e:
            return False, str(e)

    def resume_domain(self, name: str) -> tuple[bool, str]:
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            domain.resume()
            return True, f"{name} resumed."
        except libvirt.libvirtError as e:
            return False, str(e)

    def get_stats(self, name: str) -> dict:
        domain = self.get_domain(name)
        if not domain:
            return {}
        try:
            state, _ = domain.state()
            if state != libvirt.VIR_DOMAIN_RUNNING:
                return {}
            info = domain.info()
            return {
                "cpu_time_ns": info[4],
                "memory_kb":   info[2],
                "max_mem_kb":  info[1],
                "vcpus":       info[3],
            }
        except libvirt.libvirtError:
            return {}

    def open_console(self, name: str) -> tuple[bool, str]:
        import subprocess
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            subprocess.Popen(
                ["virt-viewer", "--connect", LIBVIRT_URI,
                 "--wait", "--reconnect", name],
                start_new_session=True,
            )
            return True, f"Console opened for {name}."
        except FileNotFoundError:
            return False, "virt-viewer not installed. Run: sudo dnf install virt-viewer"
        except Exception as e:
            return False, str(e)

    # ------------------------------------------------------------------ #
    # VM creation                                                          #
    # ------------------------------------------------------------------ #

    def define_domain(self, xml: str) -> tuple[bool, str]:
        """
        Define a new domain from a libvirt XML string.
        The XML is validated by libvirt before acceptance.
        """
        if not self._conn:
            return False, "Not connected to libvirt."
        try:
            domain = self._conn.defineXML(xml)
            return True, f"VM '{domain.name()}' created successfully."
        except libvirt.libvirtError as e:
            return False, str(e)

    def delete_domain(self, name: str, delete_storage: bool = False) -> tuple[bool, str]:
        """
        Undefine a domain. Optionally delete its disk images.
        Will force-stop a running domain before undefining.
        """
        domain = self.get_domain(name)
        if not domain:
            return False, f"Domain '{name}' not found."
        try:
            state, _ = domain.state()
            if state in (libvirt.VIR_DOMAIN_RUNNING, libvirt.VIR_DOMAIN_PAUSED):
                domain.destroy()

            flags = 0
            if delete_storage:
                flags |= libvirt.VIR_DOMAIN_UNDEFINE_MANAGED_SAVE
                flags |= libvirt.VIR_DOMAIN_UNDEFINE_SNAPSHOTS_METADATA
                # Remove associated storage volumes
                try:
                    domain.undefineFlags(
                        flags | libvirt.VIR_DOMAIN_UNDEFINE_NVRAM
                    )
                except libvirt.libvirtError:
                    domain.undefine()
            else:
                domain.undefine()

            # Remove from trust config if present
            if name in self._user_config:
                del self._user_config[name]
                _save_trust_config(self._user_config)

            return True, f"'{name}' deleted."
        except libvirt.libvirtError as e:
            return False, str(e)

    # ------------------------------------------------------------------ #
    # Trust level definitions management                                  #
    # ------------------------------------------------------------------ #

    def get_trust_defs(self) -> dict[str, dict]:
        """
        Returns the complete merged trust level definitions dict.
        Includes both built-in levels and any user-defined custom levels.
        """
        return _merge_trust_defs(self._user_config)

    def save_custom_trust_level(
        self,
        key: str,
        label: str,
        color: str,
    ) -> tuple[bool, str]:
        """
        Add or update a custom trust level definition.
        Built-in locked levels (system) cannot be modified.
        key must be a valid identifier (no spaces).
        """
        # Validate key: must be non-empty and contain only safe characters
        sanitised = key.replace("_", "").replace("-", "")
        if not key or not sanitised or not sanitised.isalnum():
            return False, "Trust level key must be alphanumeric (hyphens/underscores allowed)."
        if DEFAULT_TRUST_LEVELS.get(key, {}).get("locked"):
            return False, f"Cannot modify locked built-in level '{key}'."

        defs = self._user_config.setdefault("_trust_defs", {})
        existing_sorts = [
            v.get("sort", 50)
            for v in list(DEFAULT_TRUST_LEVELS.values()) + list(defs.values())
        ]
        new_sort = max(existing_sorts) + 1 if key not in defs else defs[key].get("sort", 50)

        defs[key] = {"label": label.strip(), "color": color, "sort": new_sort}
        try:
            _save_trust_config(self._user_config)
        except OSError as e:
            return False, f"Failed to save trust definition: {e}"
        self._notify()
        return True, f"Trust level '{label}' saved."

    def delete_custom_trust_level(self, key: str) -> tuple[bool, str]:
        """Delete a user-defined custom trust level."""
        if key in DEFAULT_TRUST_LEVELS:
            return False, f"Cannot delete built-in trust level '{key}'."
        defs = self._user_config.get("_trust_defs", {})
        if key not in defs:
            return False, f"Custom trust level '{key}' not found."
        del defs[key]
        _save_trust_config(self._user_config)
        self._notify()
        return True, f"Trust level '{key}' deleted."

    def get_domain_xml(self, name: str) -> str | None:
        """Return the current domain XML for inspection or cloning."""
        domain = self.get_domain(name)
        if not domain:
            return None
        try:
            return domain.XMLDesc()
        except libvirt.libvirtError:
            return None

    def build_domain_xml(
        self,
        name: str,
        vcpus: int,
        memory_mb: int,
        disk_path: str,
        disk_size_gb: int,
        iso_path: str | None,
        network: str = "bulwark-appvms",
        firmware: str = "efi",
    ) -> str:
        """
        Generates a sensible libvirt domain XML for a new VM.
        Used by the create dialog — covers the common case without
        requiring the user to write XML manually.
        """
        iso_disk = ""
        if iso_path:
            iso_disk = f"""
    <disk type='file' device='cdrom'>
      <driver name='qemu' type='raw'/>
      <source file='{iso_path}'/>
      <target dev='sda' bus='sata'/>
      <readonly/>
      <boot order='1'/>
    </disk>"""
            boot_order = "2"
        else:
            boot_order = "1"

        firmware_tag = "<os firmware='efi'>" if firmware == "efi" else "<os>"

        return f"""<domain type='kvm'>
  <name>{name}</name>
  <memory unit='MiB'>{memory_mb}</memory>
  <currentMemory unit='MiB'>{memory_mb}</currentMemory>
  <vcpu placement='static'>{vcpus}</vcpu>
  {firmware_tag}
    <type arch='x86_64' machine='q35'>hvm</type>
  </os>
  <features>
    <acpi/>
    <apic/>
  </features>
  <cpu mode='host-passthrough' check='none' migratable='off'/>
  <clock offset='utc'>
    <timer name='rtc' tickpolicy='catchup'/>
    <timer name='pit' tickpolicy='delay'/>
    <timer name='hpet' present='no'/>
  </clock>
  <on_poweroff>destroy</on_poweroff>
  <on_reboot>restart</on_reboot>
  <on_crash>destroy</on_crash>
  <devices>
    <emulator>/usr/bin/qemu-system-x86_64</emulator>
    <disk type='file' device='disk'>
      <driver name='qemu' type='qcow2' discard='unmap'/>
      <source file='{disk_path}'/>
      <target dev='vda' bus='virtio'/>
      <boot order='{boot_order}'/>
    </disk>{iso_disk}
    <interface type='network'>
      <source network='{network}'/>
      <model type='virtio'/>
    </interface>
    <graphics type='spice' autoport='yes'>
      <listen type='none'/>
      <image compression='off'/>
    </graphics>
    <video>
      <model type='virtio' heads='1' primary='yes'>
        <acceleration accel3d='no'/>
      </model>
    </video>
    <channel type='spiceport'>
      <target type='virtio' name='com.redhat.spice.0'/>
    </channel>
    <input type='tablet' bus='usb'/>
    <input type='keyboard' bus='virtio'/>
    <memballoon model='virtio'><stats period='5'/></memballoon>
    <rng model='virtio'><backend model='random'>/dev/urandom</backend></rng>
  </devices>
</domain>"""
